// Guild workspace: routeable concept pages, sharing the homepage's demo state.
paths.arrow='M5 19 19 5M5 5h14v14';paths.clock='M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0';paths.check='m5 12 4 4L19 6';paths.settings='M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2';paths.target='M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0';paths.gift='M3 8h18v4H3V8 M5 12v9h14v-9 M12 8v13 M12 8S4 8 5 4s7 0 7 4 M12 8s8 0 7-4-7 0-7 4';
const arrow=()=>icon('arrow');const ui={discoveryFilter:'all',discoveryQuery:'',sort:'volume',rankPeriod:'14',rankQuery:'',memberQuery:'',memberSort:'volume',battleTab:'overview',wizardStep:1,wizard:null};
const pageRoot=$('#workspace');let routePath='';let routeQuery=new URLSearchParams();let renderingPage=false;
const link=(path,text,cls='')=>`<a class="${cls}" href="#/${path}">${text}</a>`;
const pageTag='<span class="demo-chip">ILLUSTRATIVE DATA</span>';
function routeTo(path){if(modal.open)close();const target='#/'+path;if(location.hash===target)renderRoute();else location.hash=target}
const navigate=routeTo;
const originalRender=render;
render=function(){originalRender();if(routePath&&!renderingPage)renderRoute(false)};
showGuild=function(id){navigate('guild/'+id)};showMyGuild=function(){navigate('my-guild')};showBattle=function(){navigate('arena')};showCreate=function(){if(state.membership){navigate('my-guild');toast('Leave your current demo guild before creating another.')}else{ui.wizardStep=1;ui.wizard=null;navigate('create')}};
actions.create=showCreate;actions.myguild=showMyGuild;actions.battle=showBattle;actions.discover=()=>navigate('discover');
$('#full-ranking').onclick=()=>navigate('rankings');
function drawNav(section){const items=[['','Overview','shield'],['discover','Find a Guild','search'],['rankings','Rankings','chart'],['arena','Battle Arena','swords'],['my-guild','My Guild','users'],['forum/'+(state.membership?.id||'unisat'),'Forum','chat']];$('#guild-navigation').innerHTML=`<div class="guild-subnav"><div class="subnav-links">${items.map(([path,label,ic])=>`<a href="#/${path}" ${(section===path||section==='forum'&&path.startsWith('forum/'))?'class="current" aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}</div><button class="subnav-create" data-action="create">＋ <span>Create Guild</span></button></div>`}
function heading(kicker,title,description,extra=''){return `<div class="page-heading"><div><div class="page-eyebrow">${kicker}</div><h1 tabindex="-1">${title}</h1><p>${description}</p></div>${extra}</div>`}
function breadcrumb(items){return `<div class="breadcrumbs">${link('','Guilds')}<span>/</span>${items}</div>`}
function demoNote(text='All activity and statistics on this page are illustrative demo data.'){return `<div class="page-demo-note"><span class="blue-dot"></span>${text}</div>`}
function kpis(items){return `<div class="page-kpis">${items.map(([label,value,sub,ic])=>`<div class="page-kpi"><div class="kpi-label">${label}${ic?icon(ic):''}</div><strong>${value}</strong><small>${sub||'&nbsp;'}</small></div>`).join('')}</div>`}
function sectionTitle(title,meta='',action=''){return `<div class="workspace-panel-heading"><div><h2>${title}</h2>${meta?`<p>${meta}</p>`:''}</div>${action}</div>`}
function footer(){return `<div class="workspace-footer"><span>XOX GUILDS <i>·</i> Easy to Play. Fun to Trade.</span><span>Interactive concept ${pageTag}</span></div>`}
function chart(label='TRADING VOLUME',zero=false){const personal=label.startsWith('YOUR');const pts=zero?'0,145 60,145 120,145 180,145 240,145 300,145 360,145 420,145 480,145 540,145 600,145':'0,136 25,129 50,138 75,113 100,119 125,105 150,119 175,86 200,90 225,71 250,80 275,55 300,66 325,54 350,72 375,43 400,56 425,27 450,44 475,19 500,32 525,14 550,20 575,9 600,15';return `<div class="volume-chart"><div class="chart-legend"><span><i></i> ${label}</span><small>14-day demo view</small></div><div class="chart-canvas"><div class="chart-y"><span>${zero?'—':personal?'$12K':'$600M'}</span><span>${zero?'—':personal?'$8K':'$400M'}</span><span>${zero?'—':personal?'$4K':'$200M'}</span><span>$0</span></div><svg viewBox="0 0 600 160" role="img" aria-label="${zero?'No trading volume yet':'Illustrative trading volume trend over 14 days'}" preserveAspectRatio="none"><defs><linearGradient id="chartfill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#168dff" stop-opacity=".26"/><stop offset="100%" stop-color="#168dff" stop-opacity="0"/></linearGradient></defs><path d="M0 25H600M0 65H600M0 105H600M0 145H600" stroke="#24364c" stroke-dasharray="3 6" stroke-width="1"/><polygon points="0,160 ${pts} 600,160" fill="url(#chartfill)" stroke="none"/><polyline points="${pts}" stroke="#3da4ff" fill="none" stroke-width="2.4" vector-effect="non-scaling-stroke"/></svg></div><div class="chart-x"><span>DAY 01</span><span>DAY 04</span><span>DAY 07</span><span>DAY 10</span><span>DAY 14</span></div></div>`}
function card(g){const saved=state.saved.includes(g.id);return `<article class="guild-card page-guild-card"><div class="card-header"><img src="${emblem(g)}" alt=""><div><h3>${link('guild/'+g.id,escapeHtml(g.name))}</h3>${tier(g)}</div><button class="bookmark ${saved?'is-saved':''}" data-save="${g.id}" aria-pressed="${saved}" aria-label="${saved?'Unsave':'Save'} ${escapeHtml(g.name)}">${icon('bookmark')}</button></div><div class="style-tags">${escapeHtml(g.style||'Community · All markets').split(' · ').map(t=>`<span>${t}</span>`).join('')}</div><p class="card-description">${escapeHtml(g.description)}</p><div class="card-stats"><div><small>14D TRADING VOLUME</small><strong>${money(g.volume)}</strong></div><div><small>MEMBERS</small><strong>${g.members.toLocaleString()}</strong></div></div><div class="card-bottom"><span class="policy ${g.policy}"><i></i>${g.policy==='open'?'Open to join':'Approval required'}</span><button data-guild="${g.id}">${actionLabel(g).replace(/<svg[\s\S]*?<\/svg>/g,'')}</button></div></article>`}
function discoveryPage(){return breadcrumb('Find a Guild')+heading('YOUR PEOPLE. YOUR POTENTIAL.','FIND YOUR <span>TRADING CIRCLE.</span>','Different strategies. Shared ambition. Discover a team that moves with you.')+`<div class="discovery-featured"><div><span class="page-eyebrow">COMMUNITY SPOTLIGHT</span><h2>Built for the way <em>you trade.</em></h2><p>From analytical minds to active market explorers.<br>There’s a place for your perspective.</p><div class="spotlight-badges"><span>${icon('users')} Open communities</span><span>${icon('target')} Shared focus</span><span>${icon('shield')} Stronger connections</span></div></div><div class="spotlight-emblems"><img src="assets/stellar.webp" alt=""><img src="assets/unisat.webp" alt=""><img src="assets/alpha.webp" alt=""></div></div><div class="workspace-toolbar"><div class="page-filters" role="group" aria-label="Guild filters">${[['all','All guilds'],['open','Open to join'],['approval','Approval required'],['saved','Saved guilds']].map(([f,n])=>`<button data-page-filter="${f}" class="${ui.discoveryFilter===f?'selected':''}">${n}${f==='saved'?` <span>${state.saved.length}</span>`:''}</button>`).join('')}</div><div class="toolbar-right"><label class="search">${icon('search')}<input id="page-search" type="search" placeholder="Search guilds…" value="${escapeHtml(ui.discoveryQuery)}" aria-label="Search guilds"></label><label class="sort-select"><span>Sort:</span><select id="discovery-sort" aria-label="Sort guilds"><option value="volume" ${ui.sort==='volume'?'selected':''}>Trading volume</option><option value="members" ${ui.sort==='members'?'selected':''}>Members</option><option value="name" ${ui.sort==='name'?'selected':''}>Name A–Z</option></select></label></div></div><div class="results-meta"><span id="page-result-count"></span>${pageTag}</div><div id="page-results" class="guild-cards"></div><div class="discovery-cta"><div>${icon('shield')}<div><h3>Don’t just find a team. Build one.</h3><p>Bring your own vision to the XOX community.</p></div></div><button class="secondary" data-action="create">Create your guild ${arrow()}</button></div>`}
function updateDiscovery(){let arr=guilds().filter(g=>(ui.discoveryFilter==='all'||ui.discoveryFilter==='saved'&&state.saved.includes(g.id)||g.policy===ui.discoveryFilter)&&`${g.name} ${g.description} ${g.style}`.toLowerCase().includes(ui.discoveryQuery.toLowerCase()));arr.sort((a,b)=>ui.sort==='members'?b.members-a.members:ui.sort==='name'?a.name.localeCompare(b.name):b.volume-a.volume);$('#page-result-count').textContent=`${arr.length} guild${arr.length!==1?'s':''} to explore`;$('#page-results').innerHTML=arr.length?arr.map(card).join(''):`<div class="page-empty">${icon('search')}<h2>No guilds found.</h2><p>Try a different search or explore another membership type.</p><button class="secondary" data-page-reset>Reset filters</button></div>`}
function rankingPage(){const ordered=[...baseGuilds].sort((a,b)=>b.volume-a.volume);return breadcrumb('Rankings')+heading('THE TEAMS SETTING THE PACE','EVERY TRADE.<br><span>A SHARED AMBITION.</span>','Explore guild performance and discover the communities climbing together.',`<div class="heading-detail">${icon('trophy')}<span>GUILD LEADERBOARD<small>Demo season · Illustrative standings</small></span></div>`)+`<div class="podium">${[1,0,2].map(i=>{const g=ordered[i];return `<a class="podium-card podium-${i+1}" href="#/guild/${g.id}"><div class="podium-rank">${String(i+1).padStart(2,'0')}<span>${i===0?'THE PACESETTER':i===1?'THE CHALLENGER':'THE CONTENDER'}</span></div><img src="${emblem(g)}" alt=""><h2>${escapeHtml(g.name)}</h2><div>${tier(g)}</div><strong>${money(g.volume)}</strong><small>14D TRADING VOLUME · DEMO</small><div class="podium-foot"><span>${g.members} members</span><span>View guild ${arrow()}</span></div></a>`}).join('')}</div><div class="workspace-panel ranking-full">${sectionTitle('Guild standings','Ranked by illustrative trading volume',`<div class="periods">${[['14','14D'],['30','30D'],['all','All time']].map(([v,l])=>`<button data-rank-period="${v}" class="${ui.rankPeriod===v?'selected':''}">${l}</button>`).join('')}</div>`)}<div class="ranking-tools"><label class="search">${icon('search')}<input id="rank-search" type="search" placeholder="Find a guild in the rankings…" value="${escapeHtml(ui.rankQuery)}" aria-label="Search rankings"></label><span>Demo values · No live feed</span></div><div class="page-table-wrap"><table class="workspace-table"><thead><tr><th>RANK</th><th>GUILD</th><th>TIER / LEVEL</th><th id="rank-volume-heading">14D VOLUME</th><th>GUILD POINTS</th><th>MEMBERS</th><th>ACTIVE MEMBERS</th><th></th></tr></thead><tbody id="full-rank-rows"></tbody></table></div><div class="table-foot"><span id="rank-result-count"></span><span>All values are illustrative.</span></div></div><div class="ranking-explainer">${[['chart','Trading volume','An illustrative measure of combined guild trading activity.'],['users','Active members','Demo participation rate within each guild.'],['trophy','Guild tier','A concept progression system for growing trading communities.']].map(([ic,t,p])=>`<div>${icon(ic)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`}
function updateRanks(){const factor=ui.rankPeriod==='14'?1:ui.rankPeriod==='30'?2.17:8.62;const all=guilds().sort((a,b)=>b.volume-a.volume);const arr=all.filter(g=>g.name.toLowerCase().includes(ui.rankQuery.toLowerCase()));$('#full-rank-rows').innerHTML=arr.map(g=>{const rank=all.findIndex(x=>x.id===g.id)+1;return `<tr><td><span class="ranking-badge rank-${rank}">${String(rank).padStart(2,'0')}</span></td><td><a class="table-guild" href="#/guild/${g.id}"><img src="${emblem(g)}" alt=""><span>${escapeHtml(g.name)}<small>${g.policy==='open'?'Open to join':'Approval required'}</small></span></a></td><td>${tier(g)}</td><td class="volume-cell">${money(g.volume*factor)}</td><td>${demoPoints(g).toLocaleString()}</td><td>${g.members.toLocaleString()}</td><td><div class="table-activity"><span>${g.activity}%</span><i><b style="width:${g.activity}%"></b></i></div></td><td>${link('guild/'+g.id,arrow(),'row-link')}</td></tr>`}).join('')||'<tr><td colspan="7" class="table-empty">No guilds match your search.</td></tr>';$('#rank-result-count').textContent=`Showing ${arr.length} of ${all.length} guilds`;$('#rank-volume-heading').textContent=(ui.rankPeriod==='14'?'14D':ui.rankPeriod==='30'?'30D':'ALL-TIME')+' VOLUME'}
const memberNames=['SatoshiWave','BlueHorizon','DeltaMind','NorthStar','VectorX','CipherTrade','Zenith','NovaSignal','Atlas','QuietAlpha','Moonline','EdgeFinder'];
function roster(g){if(state.drafts.some(x=>x.id===g.id))return state.membership?.id===g.id?[{name:state.membership.name,role:'Founder',volume:0,points:0,initial:'F',isYou:true}]:[];const data=memberNames.map((name,i)=>({name,role:i===0?'Leader':i===1?'Co-leader':'Member',volume:Math.round(g.volume*1e9/(24+i*5)),points:Math.round(120000/(1+i*.4)),initial:name.slice(0,1),isYou:false}));if(state.membership?.id===g.id)data.push({name:state.membership.name,role:'Member',volume:0,points:0,initial:state.membership.name.slice(0,1),isYou:true});return data}
const compactMoney=v=>v===0?'$0.00':v>=1e6?'$'+(v/1e6).toFixed(2)+'M':'$'+v.toLocaleString();
function profileHero(g,isMine=false,preview=false){const rank=guildRank(g);const own=state.membership?.id===g.id;return `<section class="profile-hero"><div class="profile-hero-glow"></div><div class="profile-identity"><div class="profile-emblem"><img src="${emblem(g)}" alt=""></div><div><div class="page-eyebrow">${isMine?'YOUR TRADING COMMUNITY':'XOX TRADING GUILD'} <span class="profile-rank">#${rank} IN DEMO RANKINGS</span></div><h1 tabindex="-1">${escapeHtml(g.name)}</h1><div class="profile-badges">${tier(g)}<span class="policy ${g.policy}"><i></i>${g.policy==='open'?'Open to join':'Approval required'}</span></div><p>${escapeHtml(g.description)}</p></div></div><div class="profile-actions">${isMine?`<span class="member-pill">${icon('check')} ${preview?'Member preview':state.membership?.role==='owner'?'Guild founder':'Guild member'}</span><button class="secondary" data-share="${g.id}">${icon('users')} Invite a friend</button>`:`<button class="primary" ${state.pending.includes(g.id)?'disabled':''} ${own?'data-action="myguild"':`data-join="${g.id}"`}>${own?'Go to My Guild':state.pending.includes(g.id)?'Application pending':g.policy==='open'?'Join guild':'Apply to join'} ${arrow()}</button><button class="secondary" data-profile-save="${g.id}">${icon('bookmark')} ${state.saved.includes(g.id)?'Saved':'Save guild'}</button>`}</div></section>`}
function profileTabs(g,tab){return `<div class="page-tabs" role="navigation" aria-label="Guild profile sections">${[['overview','Overview'],['members','Members'],['activity','Activity']].map(([id,l])=>link('guild/'+g.id+(id==='overview'?'':'/'+id),l,tab===id?'selected':'')).join('')}<span>GUILD PROFILE ${pageTag}</span></div>`}
function guildPage(id,tab='overview'){const g=guildById(id);if(!g)return notFound();return breadcrumb(`${link('discover','Find a Guild')}<span>/</span>${escapeHtml(g.name)}`)+profileHero(g)+profileTabs(g,tab)+demoNote()+ (tab==='members'?membersPage(g):tab==='activity'?activityPage(g):profileOverview(g))}
function profileOverview(g){const custom=state.drafts.some(x=>x.id===g.id);return kpis([['14D TRADING VOLUME',money(g.volume),'Combined guild activity','chart'],['GUILD POINTS',demoPoints(g).toLocaleString(),'Illustrative team points','trophy'],['MEMBERS',g.members.toLocaleString(),'Growing together','users'],['ACTIVE MEMBERS',g.activity+'%',custom?'Your team starts here':'Demo participation rate','target']])+`<div class="content-grid"><section class="workspace-panel">${sectionTitle('The team in motion','Trading volume over the past 14 days',pageTag)}${chart('GUILD TRADING VOLUME',g.volume===0)}</section><aside class="workspace-panel guild-about">${sectionTitle('About the guild')}<p>${escapeHtml(g.description)}</p><div class="about-row"><span>Trading focus</span><strong>${escapeHtml(g.style||'Community · All markets')}</strong></div><div class="about-row"><span>Membership</span><strong>${g.policy==='open'?'Open to join':'Approval required'}</strong></div><div class="about-row"><span>Guild level</span><strong>Level ${g.level} · ${g.tier}</strong></div><div class="about-note">${icon('shield')} Built on shared ambition.<br>Grow with a team that shares your perspective.</div></aside></div><div class="content-grid profile-bottom"><section class="workspace-panel">${sectionTitle('The people behind the progress','Sample contributor roster',link('guild/'+g.id+'/members','View members '+arrow(),'text-button'))}${contributorList(g)}</section><section class="workspace-panel journey-panel">${sectionTitle('The next level is a team effort','Guild progression concept')}<div class="tier-journey"><div>${icon('shield')}<span>${g.tier}</span><small>LEVEL ${g.level}</small></div><div class="journey-track"><i></i><span>BUILD TOGETHER</span></div><div>${icon('trophy')}<span>Next chapter</span><small>GROW AS A TEAM</small></div></div><p>Progression criteria and rewards will be defined by the production guild system.</p></section></div>`}
function contributorList(g){const members=roster(g).slice(0,4);return members.length?`<div class="contributor-list">${members.map((m,i)=>`<div><span class="contributor-number">${String(i+1).padStart(2,'0')}</span><span class="avatar avatar-${i%4}">${escapeHtml(m.initial)}</span><div><strong>${escapeHtml(m.name)}${m.isYou?' <small>YOU</small>':''}</strong><small>${m.role}</small></div><span>${compactMoney(m.volume)}<small>14D VOLUME</small></span></div>`).join('')}</div>`:`<div class="inline-empty">${icon('users')}<p>Your first member is the start of something bigger.</p></div>`}
function membersPage(g){return `<div class="workspace-panel">${sectionTitle('A shared edge. A stronger team.',`${g.members.toLocaleString()} guild members · ${state.drafts.some(x=>x.id===g.id)?'Local demo guild':'Sample roster, not the complete membership'}`)}<div class="ranking-tools"><label class="search">${icon('search')}<input id="member-search" type="search" placeholder="Search sample members…" value="${escapeHtml(ui.memberQuery)}" aria-label="Search members"></label><label class="sort-select"><span>Sort:</span><select id="member-sort"><option value="volume" ${ui.memberSort==='volume'?'selected':''}>Trading volume</option><option value="points" ${ui.memberSort==='points'?'selected':''}>Guild points</option><option value="name" ${ui.memberSort==='name'?'selected':''}>Name A–Z</option></select></label></div><div class="page-table-wrap"><table class="workspace-table"><thead><tr><th>#</th><th>TRADER</th><th>ROLE</th><th>14D VOLUME</th><th>GUILD POINTS</th><th>PROFILE</th></tr></thead><tbody id="member-rows"></tbody></table></div><div class="table-foot"><span id="member-result-count"></span><span>Sample profiles · Demonstration only</span></div></div>`}
function updateMembers(g){const arr=roster(g).filter(m=>m.name.toLowerCase().includes(ui.memberQuery.toLowerCase())).sort((a,b)=>ui.memberSort==='name'?a.name.localeCompare(b.name):ui.memberSort==='points'?b.points-a.points:b.volume-a.volume);$('#member-rows').innerHTML=arr.map((m,i)=>`<tr><td class="dim">${String(i+1).padStart(2,'0')}</td><td><div class="table-guild"><span class="avatar avatar-${i%4}">${escapeHtml(m.initial)}</span><span>${escapeHtml(m.name)}${m.isYou?' <b class="you-label">YOU</b>':''}<small>${m.isYou?'Your local demo profile':'Sample trader profile'}</small></span></div></td><td><span class="role-badge ${m.role==='Leader'||m.role==='Founder'?'leader':''}">${m.role}</span></td><td>${compactMoney(m.volume)}</td><td>${m.points.toLocaleString()}</td><td><span class="sample-label">${m.isYou?'LOCAL':'DEMO'}</span></td></tr>`).join('')||'<tr><td colspan="6" class="table-empty">No members match your search.</td></tr>';$('#member-result-count').textContent=`${arr.length} ${state.drafts.some(x=>x.id===g.id)?'local':'sample'} profile${arr.length===1?'':'s'}`}
function activityPage(g){const custom=state.drafts.some(x=>x.id===g.id);return `<div class="content-grid"><section class="workspace-panel">${sectionTitle('Every milestone tells a story','Illustrative guild activity')}<div class="timeline">${(custom?[['shield','Your guild journey begins','Guild created locally on this device.','YOUR FIRST CHAPTER']]:[['trophy','A new milestone for the team','The guild reached a new illustrative volume milestone.','SAMPLE EVENT 01'],['users','A growing trading circle','New traders joined the community in this example timeline.','SAMPLE EVENT 02'],['shield','Building a shared legacy','The guild progressed to its current demonstration tier.','SAMPLE EVENT 03'],['chart','The journey started here','A team came together around a shared trading ambition.','SAMPLE EVENT 04']]).map(([ic,t,p,d])=>`<div class="timeline-item"><span>${icon(ic)}</span><div><small>${d}</small><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></section><aside class="workspace-panel activity-side">${icon('users')}<h2>Be part of the next chapter.</h2><p>The strongest communities are built one connection at a time.</p><button class="primary" ${state.membership?.id===g.id?'data-action="myguild"':`data-join="${g.id}"`}>${state.membership?.id===g.id?'Open My Guild':'Explore membership'} ${arrow()}</button><small>Illustrative timeline · No live activity feed</small></aside></div>`}
function arenaFormat(){return `<div class="content-grid"><section class="workspace-panel">${sectionTitle('Clear rules. A shared ambition.','Proposed format — not confirmed product rules')}<div class="format-list">${[['01','Build the team','Join a guild before entering a future competition. Eligibility and roster rules would be published in advance.'],['02','Know the playing field','A competition would need a defined window, scoring measure and fair participation requirements.'],['03','Follow team progress','A dedicated match view could show verified contributions and aggregate team performance.'],['04','See a transparent result','Final results would need to be verified before any reward or settlement.']].map(([n,t,p])=>`<div><span>${n}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></section><aside class="workspace-panel rule-summary">${sectionTitle('Before the first battle')}<div class="rule-state"><span>Competition window</span><strong>To be confirmed</strong></div><div class="rule-state"><span>Scoring method</span><strong>To be confirmed</strong></div><div class="rule-state"><span>Eligibility</span><strong>To be confirmed</strong></div><div class="rule-state"><span>Reward allocation</span><strong>To be confirmed</strong></div><div class="notice">The arena is a design preview. There is no active event, entry fee, enrollment or reward commitment.</div></aside></div>`}
function arenaRewards(){return `<div class="workspace-panel reward-concept"><div class="reward-concept-art">${icon('trophy')}</div><span class="page-eyebrow">A SHARED ACHIEVEMENT</span><h2>Something to build toward.<br><span>Something to celebrate together.</span></h2><p>Team milestones, guild recognition and clearly defined reward experiences are part of the arena design concept.</p><div class="reward-concept-cards"><div>${icon('shield')}<strong>Guild recognition</strong><small>Concept achievement badges</small></div><div>${icon('trophy')}<strong>Team milestones</strong><small>Celebrate collective progress</small></div><div>${icon('gift')}<strong>Reward clarity</strong><small>Verified rules before competition</small></div></div><div class="notice">No reward pool, token amount, points allocation or claim is available. Final terms require production confirmation.</div></div>`}
function dashboardTabs(tab,preview){const p=preview?'?preview=1':'';return `<div class="page-tabs dashboard-tabs" role="navigation" aria-label="My Guild sections">${[['overview','Dashboard'],['members','Members'],['missions','Missions & rewards'],['settings','Guild settings']].map(([id,n])=>link('my-guild'+(id==='overview'?'':'/'+id)+p,n,tab===id?'selected':'')).join('')}<span>${preview?'MEMBER PREVIEW':'YOUR GUILD WORKSPACE'}</span></div>`}
function myGuildPage(tab='overview',preview=false){const g=preview?guildById('unisat'):state.membership&&guildById(state.membership.id);if(!g)return emptyMyGuild();return breadcrumb('My Guild')+(preview?`<div class="preview-banner"><div>${icon('shield')} You’re viewing a sample member dashboard. Your actual membership has not changed.</div>${link('my-guild','Exit preview ×')}</div>`:'')+profileHero(g,true,preview)+dashboardTabs(tab,preview)+demoNote(preview?'Sample dashboard · Every number and profile here is illustrative.':'Your membership is stored on this device. Trading and rewards are not connected.')+(tab==='members'?membersPage(g):tab==='missions'?missionsPage(g,preview):tab==='settings'?settingsPage(g,preview):dashboardOverview(g,preview))}
function emptyMyGuild(){return breadcrumb('My Guild')+heading('YOUR NEXT CHAPTER','A SHARED EDGE<br><span>STARTS WITH YOUR TEAM.</span>','Discover your people, or bring your own trading circle together.')+`<div class="empty-guild-layout"><section class="empty-guild-main"><div class="empty-guild-art"><img src="assets/unisat.webp" alt=""><span class="orbit orbit-1"></span><span class="orbit orbit-2"></span></div><span class="page-eyebrow">YOUR PLACE IN THE COMMUNITY</span><h2>Your team is out there.</h2><p>You haven’t joined a demo guild yet.<br>Find a community that shares your ambition.</p><div class="empty-guild-actions">${link('discover','Find a Guild '+arrow(),'primary button')}<button class="secondary" data-action="create">Create Guild ＋</button></div><a class="preview-link" href="#/my-guild?preview=1">Preview a member dashboard ${arrow()}</a></section><aside><div class="workspace-panel next-steps">${sectionTitle('A new kind of trading circle')}<div>${icon('users')}<h3>Find your people</h3><p>Explore communities with a shared trading focus.</p></div><div>${icon('chart')}<h3>Contribute together</h3><p>Build toward a collective guild journey.</p></div><div>${icon('trophy')}<h3>Grow your legacy</h3><p>Make team milestones part of your story.</p></div></div><div class="workspace-panel applications-panel">${sectionTitle('Your applications',state.pending.length?'Saved locally · Not sent to guild leaders':'No pending applications')}<div class="application-list">${state.pending.length?state.pending.map(id=>{const g=guildById(id);return `<div><img src="${emblem(g)}" alt=""><div><strong>${escapeHtml(g.name)}</strong><small>Demo application saved</small></div><button data-cancel="${id}">Cancel</button></div>`}).join(''):'<p>Your applications will appear here when you explore approval-based guilds.</p>'}</div></div></aside></div>`}
function settingsPage(g,preview){const owner=!preview&&state.membership?.role==='owner'&&state.drafts.some(x=>x.id===g.id);return `<div class="settings-layout"><aside class="settings-context"><span>${icon('settings')}</span><h2>Make it your own.</h2><p>${owner?'Shape the identity of your local demo guild. Changes are saved on this device.':'Guild identity is managed by the founder. Your profile and membership details are shown here.'}</p><div class="settings-role"><small>YOUR ROLE</small><strong>${owner?'Guild founder':'Guild member'}</strong></div></aside><section><div class="workspace-panel settings-panel">${sectionTitle('Guild identity',owner?'Keep your community’s story clear and focused.':'Read-only guild details')}<form id="guild-settings-form" class="form"><label for="setting-name">Guild name</label><input name="name" id="setting-name" required minlength="3" maxlength="28" value="${escapeHtml(g.name)}" ${owner?'':'disabled'}><label for="setting-description">Guild description</label><textarea name="description" id="setting-description" required minlength="10" maxlength="180" rows="3" ${owner?'':'disabled'}>${escapeHtml(g.description)}</textarea><div class="row"><div><label for="setting-policy">Membership policy</label><select name="policy" id="setting-policy" ${owner?'':'disabled'}><option value="open" ${g.policy==='open'?'selected':''}>Open to join</option><option value="approval" ${g.policy==='approval'?'selected':''}>Approval required</option></select></div><div><label for="setting-focus">Trading focus</label><select name="style" id="setting-focus" ${owner?'':'disabled'}>${[...new Set([g.style||'Community · All markets','Community · All markets','Quantitative · BTC & ETH','Learning · Open community','Active trading · All markets','Risk-focused · Majors'])].map(s=>`<option ${s===g.style?'selected':''}>${s}</option>`).join('')}</select></div></div>${owner?'<div class="settings-save"><span>Saved locally · No production changes</span><button class="primary" type="submit">Save guild settings</button></div>':'<div class="notice">Only a local demo guild founder can edit guild settings. Production roles and permissions are not connected.</div>'}</form></div><div class="workspace-panel membership-settings">${sectionTitle('Your membership',preview?'Sample member profile':'Manage your browser-local demo membership')}<div><div><strong>${preview?'Demo Trader':escapeHtml(state.membership?.name||'Trader')}</strong><p>${owner?'Founder':'Member'} of ${escapeHtml(g.name)}</p></div>${preview?'<span class="sample-label">PREVIEW ONLY</span>':'<button class="secondary danger" data-action="leave">Leave demo guild</button>'}</div></div></section></div>`}
function notFound(){return `<div class="page-empty">${icon('search')}<span class="page-eyebrow">PAGE NOT FOUND</span><h1>This path needs a new direction.</h1><p>Explore the guilds and find your next chapter.</p>${link('discover','Find a Guild '+arrow(),'primary button')}</div>`}
function renderRoute(scroll=true){if(renderingPage)return;renderingPage=true;const raw=location.hash.slice(1);const normalized=raw.startsWith('/')?raw.slice(1):'';const [path,qs]=normalized.split('?');const parts=(path||'').split('/').filter(Boolean);routePath=parts.join('/');routeQuery=new URLSearchParams(qs||'');const section=parts[0]||'';drawNav(section==='guild'?'discover':section);$('#overview').hidden=!!section;pageRoot.hidden=!section;if(section){let html='';if(section==='discover')html=discoveryPage();else if(section==='rankings')html=rankingPage();else if(section==='guild')html=guildPage(parts[1],parts[2]);else if(section==='arena')html=arenaPage(parts[1]);else if(section==='my-guild')html=myGuildPage(parts[1],routeQuery.get('preview')==='1');else if(section==='competition')html=competitionPage(parts[1]);else if(section==='leaders')html=leadersPage(parts[1]);else if(section==='forum')html=forumPage(parts[1]);else if(section==='create')html=wizardPage();else html=notFound();pageRoot.innerHTML=html+footer();if(section==='discover')updateDiscovery();if(section==='rankings')updateRanks();if(parts[2]==='members'&&section==='guild'){const g=guildById(parts[1]);if(g&&$('#member-rows'))updateMembers(g)}if(section==='my-guild'&&parts[1]==='members'){const g=routeQuery.get('preview')==='1'?guildById('unisat'):state.membership&&guildById(state.membership.id);if(g&&$('#member-rows'))updateMembers(g)}const title=pageRoot.querySelector('h1')?.textContent||'Guild Workspace';document.title=title+' — XOX Guilds';}else{document.title='XOX Guilds — Stronger Together'}renderingPage=false;if(scroll){window.scrollTo({top:0,behavior:'instant'});pageRoot.querySelector('h1')?.focus({preventScroll:true})}}
function captureWizard(){const form=$('#create-form');const data=new FormData(form);ui.wizard={name:String(data.get('name')||'').trim(),description:String(data.get('description')||'').trim(),policy:data.get('policy')||'open',style:data.get('style')||'Community · All markets'}}
function activeGuild(){return routePath.startsWith('guild/')?guildById(routePath.split('/')[1]):routeQuery.get('preview')==='1'?guildById('unisat'):state.membership&&guildById(state.membership.id)}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;if(el.hasAttribute('data-page-reset')){ui.discoveryFilter='all';ui.discoveryQuery='';renderRoute(false)}if(el.dataset.pageFilter){ui.discoveryFilter=el.dataset.pageFilter;document.querySelectorAll('[data-page-filter]').forEach(b=>b.classList.toggle('selected',b===el));updateDiscovery()}if(el.dataset.rankPeriod){ui.rankPeriod=el.dataset.rankPeriod;document.querySelectorAll('[data-rank-period]').forEach(b=>b.classList.toggle('selected',b===el));updateRanks()}if(el.dataset.profileSave){const id=el.dataset.profileSave;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save()}if(el.dataset.share){const url=location.origin+location.pathname+'#/guild/'+el.dataset.share;try{await navigator.clipboard.writeText(url);toast('Guild profile link copied.')}catch{open(`<div class="modal-eyebrow">INVITE YOUR CIRCLE</div><h2>A shared journey starts here.</h2><p>Copy this profile link to share the demo.</p><input class="share-input" value="${escapeHtml(url)}" readonly aria-label="Guild profile link">`);content.querySelector('input').select()}}if(el.hasAttribute('data-wizard-next')){const fields=ui.wizardStep===1?['#guild-name','#guild-description']:[];for(const s of fields){if(!$(s).reportValidity())return}captureWizard();if(ui.wizardStep===1&&guilds().some(g=>g.name.toLowerCase()===ui.wizard.name.toLowerCase())){toast('That guild name is already in use. Try another.');return}ui.wizardStep=Math.min(3,ui.wizardStep+1);renderRoute(false);pageRoot.querySelector('.wizard-form-step:not([hidden]) h2')?.scrollIntoView({block:'nearest'})}if(el.hasAttribute('data-wizard-prev')){captureWizard();ui.wizardStep=Math.max(1,ui.wizardStep-1);renderRoute(false)}});
document.addEventListener('input',e=>{if(e.target.id==='page-search'){ui.discoveryQuery=e.target.value;updateDiscovery()}if(e.target.id==='rank-search'){ui.rankQuery=e.target.value;updateRanks()}if(e.target.id==='member-search'){ui.memberQuery=e.target.value;const g=activeGuild();if(g&&$('#member-rows'))updateMembers(g)}});
document.addEventListener('change',e=>{if(e.target.id==='discovery-sort'){ui.sort=e.target.value;updateDiscovery()}if(e.target.id==='member-sort'){ui.memberSort=e.target.value;updateMembers(activeGuild())}if(e.target.name==='policy'){document.querySelectorAll('.policy-option').forEach(x=>x.classList.toggle('chosen',x.querySelector('input').checked))}});
document.addEventListener('submit',e=>{if(e.target.id!=='guild-settings-form')return;e.preventDefault();if(routeQuery.get('preview')==='1'||state.membership?.role!=='owner')return;const g=state.drafts.find(x=>x.id===state.membership.id);if(!g)return;const f=new FormData(e.target);const name=f.get('name').trim(),description=f.get('description').trim();if(name.length<3||description.length<10){toast('Enter a guild name and a short description.');return}if(guilds().some(x=>x.id!==g.id&&x.name.toLowerCase()===name.toLowerCase())){toast('That guild name is already in use.');return}Object.assign(g,{name,description,policy:f.get('policy'),style:f.get('style')});save();toast('Guild settings saved on this device.')});
window.addEventListener('hashchange',()=>{if(modal.open)close();ui.memberQuery='';renderRoute()});
// Keep an implicit Enter submission inside the creation wizard on its current step.
document.addEventListener('submit',e=>{if(e.target.id==='create-form'&&routePath==='create'&&ui.wizardStep<3){e.preventDefault();e.stopImmediatePropagation();pageRoot.querySelector('[data-wizard-next]')?.click()}},true);
